def sh(s): return '#!/usr/bin/env bash\n'+s+'\n'
course('bash','Bash','bash','Examples use Bash 4.4 or later.','Use a terminal with Bash. Save each example as lesson.sh and run bash lesson.sh. These practice scripts do not delete or change files.','Bash is a shell language. It is useful for joining commands and automating small terminal jobs.',[
L('first-message','Print a greeting','printf writes formatted text. %s inserts a string and backslash-n ends the line.',sh('printf \'%s\\n\' \'Hello, Asha!\''),'Hello, Asha!','Change the greeting.','Use a fixed format string so data is not mistaken for formatting.'),
L('variables','Store a text value','A variable assignment has no spaces around equals. Dollar-name reads the value.',sh('name="Asha"\nprintf \'%s\\n\' "$name"'),'Asha','Use a different name.','Quote variable expansions so spaces stay inside one value.'),
L('arithmetic','Add whole numbers','Double parentheses with a dollar sign evaluate integer arithmetic.',sh('pencils=3\nprintf \'%s\\n\' "$((pencils + 2))"'),'5','Start with 6 pencils.','Bash arithmetic uses whole numbers, not decimal fractions.'),
L('choices','Choose a message','[[ ... ]] tests a rule. -ge means greater than or equal for whole numbers.',sh('score=8\nif [[ "$score" -ge 5 ]]; then\n printf \'Pass\\n\'\nelse\n printf \'Try again\\n\'\nfi'),'Pass','Try score=3.','Use spaces inside [[ and ]] and finish the block with fi.'),
L('arrays','Read an array item','A Bash array keeps indexed values. Its first position is zero.',sh('pets=(cat dog)\nprintf \'%s\\n\' "${pets[1]}"'),'dog','Read index 0.','Braces are needed around an indexed variable expansion.'),
L('loops','Visit each value','A for loop repeats its body for each word in a list.',sh('for n in 1 2 3; do\n printf \'%s\\n\' "$n"\ndone'),'1\n2\n3','Add 4 to the list.','Use "$@" or quoted array expansion when looping over values with spaces.'),
L('functions','Name a set of commands','A function groups commands. $1 is its first input.',sh('greet() { printf \'Hi, %s!\\n\' "$1"; }\ngreet "Ravi"'),'Hi, Ravi!','Call greet with your name.','Function inputs are positional; quote them when reading.'),
L('case','Match a label','case chooses commands from text patterns. ;; ends one branch.',sh('light=green\ncase "$light" in\n red) printf \'Stop\\n\' ;;\n green) printf \'Go\\n\' ;;\n *) printf \'Wait\\n\' ;;\nesac'),'Go','Try light=yellow.','End the whole choice with esac.'),
L('fallbacks','Use a default value','${name:-Guest} uses Guest when name is unset or empty.',sh('name=""\nprintf \'%s\\n\' "${name:-Guest}"'),'Guest','Set name to Asha.','The colon makes an empty value use the fallback too.'),
L('length','Count text characters','${#name} gives the length of the variable value.',sh('name="Asha"\nprintf \'%s\\n\' "${#name}"'),'4','Try a five-letter name.','For these examples use simple English letters so character counting is clear.'),
L('exit-status','Read a command status','A command returns an exit status. Zero usually means success. $? reads the last status.',sh('(exit 3)\nstatus=$?\nprintf \'%s\\n\' "$status"'),'3','Try exit 0.','Read $? immediately; the next command replaces it.'),
L('prefixes','Remove a text prefix','The # expansion removes a matching prefix from a value.',sh('file="notes.txt"\nprintf \'%s\\n\' "${file#notes}"'),'.txt','Use the prefix note instead.','This edits the displayed text value; it does not rename a file.')])
course('powershell','PowerShell','powershell','Examples use PowerShell 7 or later.','Open PowerShell 7. Paste one example or save it as lesson.ps1 and run pwsh -NoProfile -File lesson.ps1. No administrator access is needed.','PowerShell is a shell and scripting language. Its pipelines can carry objects with named properties.',[
L('first-message','Print a greeting','Write-Output sends a value to the output stream. Here it appears in the terminal.','Write-Output "Hello, Asha!"','Hello, Asha!','Change the name.','Write-Output sends data; Write-Host is mainly for host display.'),
L('variables','Keep a named value','PowerShell variable names start with a dollar sign.','$pencils = 3\nWrite-Output ($pencils + 2)','5','Start with 6 pencils.','Use parentheses when passing a calculation as one argument.'),
L('strings','Build a message','Double-quoted strings expand variables inside the text.','$name = "Ravi"\nWrite-Output "Hi, $name!"','Hi, Ravi!','Include a score in a message.','Single quotes keep the dollar text literal.'),
L('choices','Choose an action','-ge compares numbers using greater-than-or-equal. if chooses a block.','$score = 8\nif ($score -ge 5) { "Pass" } else { "Try again" }','Pass','Try score 3.','PowerShell comparisons use names such as -eq and -ge.'),
L('arrays','Read an array item','An array holds several values. Its first index is zero.','$pets = @("cat", "dog")\nWrite-Output $pets[1]','dog','Read the first item.','Use @() when you need an array shape even with one item.'),
L('foreach','Visit every item','foreach runs its block for each value in a group.','foreach ($n in 1..3) { Write-Output $n }','1\n2\n3','Count up to 4.','The loop variable holds one item, not the whole group.'),
L('hashtables','Read a named key','A hashtable pairs keys with values. Brackets select a value by key.','$book = @{ Title = "Moon Trip"; Pages = 24 }\nWrite-Output $book["Title"]','Moon Trip','Read Pages instead.','Separate hashtable entries with a semicolon or a new line.'),
L('objects','Make named properties','A custom object groups properties. Dot notation reads a property.','$book = [pscustomobject]@{ Title = "Moon Trip"; Pages = 24 }\nWrite-Output $book.Pages','24','Add an Author property.','Object properties and a formatted display are not the same thing.'),
L('filtering','Filter pipeline values','Where-Object keeps values that pass a rule. $_ means the current pipeline item.','4, 8, 9 | Where-Object { $_ -ge 7 }','8\n9','Raise the limit to 9.','Write the rule inside a script block with braces.'),
L('mapping','Transform pipeline values','ForEach-Object runs a block for each incoming value.','2, 3 | ForEach-Object { $_ * 2 }','4\n6','Multiply by 3.','Use $_ for the current item inside the pipeline block.'),
L('functions','Name reusable steps','A function can declare inputs with param. An unassigned expression becomes output.','function Get-Twice { param([int]$Number) $Number * 2 }\nGet-Twice -Number 4','8','Pass -Number 7.','Extra expressions in a function can also become output.'),
L('errors','Handle a terminating error','try and catch handle a terminating error. throw creates one here.','try { throw "Missing score" } catch { Write-Output "Try again" }','Try again','Change the message in catch.','Many command errors need -ErrorAction Stop to be caught by try/catch.')])
